def to_int(card):
    return RANKS.index(card[0]) * 4 + SUITS.index(card[1])


def hand_key(hole):
    a, b = RANKS.index(hole[0][0]), RANKS.index(hole[1][0])
    if a < b:
        a, b = b, a
    if a == b:
        return RANKS[a] + RANKS[b]
    return RANKS[a] + RANKS[b] + ("s" if hole[0][1] == hole[1][1] else "o")


def eq_vs_range(cls, f):
    row = EQR[cls]
    if f <= F[0]:
        return row[0]
    for i in range(1, len(F)):
        if f <= F[i]:
            t = (f - F[i - 1]) / (F[i] - F[i - 1])
            return row[i - 1] * (1 - t) + row[i] * t
    return row[-1]


def clamp(x, lo, hi):
    return lo if x < lo else hi if x > hi else x


def layered_win(parts, hero, dead):
    """Chips hero collects. parts: [(total_contrib, score)] of players still in
    (hero at index `hero`); dead: contributions of folded players."""
    levels = sorted(set(c for c, _ in parts))
    prev = 0
    win = 0.0
    for L in levels:
        layer = 0
        for c, _ in parts:
            layer += min(c, L) - min(c, prev)
        for d in dead:
            layer += min(d, L) - min(d, prev)
        best = -1
        nw = 0
        hero_in = False
        for i, (c, sc) in enumerate(parts):
            if c >= L:
                if sc > best:
                    best = sc
                    nw = 1
                    hero_in = (i == hero)
                elif sc == best:
                    nw += 1
                    if i == hero:
                        hero_in = True
        if hero_in:
            win += layer / float(nw)
        prev = L
    extra = sum(max(0, d - prev) for d in dead)
    if extra and parts:
        best = max(sc for c, sc in parts if c >= prev)
        ws = [i for i, (c, sc) in enumerate(parts) if c >= prev and sc == best]
        if hero in ws:
            win += extra / float(len(ws))
    return win


class Stats:
    __slots__ = ("hands", "vpip", "pfr", "big", "pbet", "pcall", "pcheck", "faced", "ffold",
                 "f3", "f3fold", "sd", "sdwin", "o3", "o3fold", "bdef", "bfold", "sda", "sdw")

    def __init__(self):
        for k in Stats.__slots__:
            setattr(self, k, 0)


def level_of(h1, h2, bd):
    """0 air / board-only, 1 weak (underpair-ish), 2 top pair+, 3 strong; on a complete board."""
    brc = [0] * 13
    for c in bd:
        brc[c >> 2] += 1
    top = max(c >> 2 for c in bd)
    bpairs = set(r for r in range(13) if brc[r] >= 2)
    v = evaluate(list(bd) + [h1, h2])
    cat = v >> 20
    if cat >= 4:
        return 3
    if cat == 3:
        return 0 if brc[(v >> 8) & 15] >= 3 else 3
    if cat == 2:
        p1, p2 = (v >> 8) & 15, (v >> 4) & 15
        if p1 in bpairs and p2 in bpairs:
            return 0
        if p1 in bpairs or p2 in bpairs:
            o = p2 if p1 in bpairs else p1
            return 2 if o >= top else 1
        return 3
    if cat == 1:
        pr = (v >> 12) & 15
        return 0 if pr in bpairs else (2 if pr >= top else 1)
    return 0


def level_street(h1, h2, bd):
    """Same 4 levels as simulate() on a board of 3-5 cards (flush draws count as weak before the river)."""
    brc = [0] * 13
    sc = [0, 0, 0, 0]
    for c in bd:
        brc[c >> 2] += 1
        sc[c & 3] += 1
    v = evaluate(list(bd) + [h1, h2])
    if len(bd) < 5 and v < (1 << 20):
        for st in range(4):
            if sc[st] + ((h1 & 3) == st) + ((h2 & 3) == st) == 4 and ((h1 & 3) == st or (h2 & 3) == st):
                return 1
    top = max(c >> 2 for c in bd)
    bpairs = set(r for r in range(13) if brc[r] >= 2)
    cat = v >> 20
    if cat >= 4:
        return 3
    if cat == 3:
        return 0 if brc[(v >> 8) & 15] >= 3 else 3
    if cat == 2:
        p1, p2 = (v >> 8) & 15, (v >> 4) & 15
        if p1 in bpairs and p2 in bpairs:
            return 0
        if p1 in bpairs or p2 in bpairs:
            o = p2 if p1 in bpairs else p1
            return 2 if o >= top else 1
        return 3
    if cat == 1:
        pr = (v >> 12) & 15
        return 0 if pr in bpairs else (2 if pr >= top else 1)
    return 0


SIZE_EDGES = (0.25, 0.45, 0.7, 0.95, 1.3)    # bet / pot buckets 0..5; 6 = raise over a bet


def size_bucket(frac, over_bet):
    if over_bet:
        return 6
    for i, e in enumerate(SIZE_EDGES):
        if frac < e:
            return i
    return 5


